import os
from security_client import KmsClient

# Use HashiCorp Vault as the concrete provider (identifiable by the service name)
client = KmsClient(
    service="HashiCorp Vault",
    address=os.getenv("VAULT_ADDR"),
    token=os.getenv("VAULT_TOKEN"),
)


def envelope_encrypt(plaintext: str, data_key: str) -> dict:
    """Envelope encrypt a payload using a data key generated by Vault.

    Returns the envelope envelope containing the encrypted data key and the encrypted plaintext.
    """
    # Generate a data key via Vault's transit secrets engine
    key_response = client.generate_data_key(
        key_name=data_key, plaintext=plaintext.encode()
    )
    # The response contains encrypted data key + encrypted plaintext
    return {
        "EncryptedDataKey": key_response["EncryptedDataKey"],
        "EncryptedPlaintext": key_response["EncryptedPlaintext"],
    }
